class CanonicalStagedInputCursorTest {
	private static final int PARTITION_COUNT = 4;

	@TempDir
	Path temporaryDirectory;

	static List<BulkCodec> codecs() {
		return List.of(BulkCodec.NONE, BulkCodec.FAST, BulkCodec.level(1), BulkCodec.level(9), BulkCodec.level(17));
	}

	@ParameterizedTest
	@MethodSource("codecs")
	void boundedChunksMatchTheVisitorAcrossFramesAndRetainTheirOwnKeys(BulkCodec codec) throws Exception {
		List<ExpectedRecord> expected = recordsForPartition(0, 5);
		Path bucket = bucketPath(temporaryDirectory, 0);
		writeFrames(bucket, codec, expected);
		CanonicalStagedInput input = stagedInput(codec);

		List<String> visitorRecords = new ArrayList<>();
		input.forEachPartitionValue(0,
				(partition, hash, roles, key) -> visitorRecords.add(view(partition, hash, roles, key)));
		List<String> cursorRecords = new ArrayList<>();
		byte[] retainedKey;
		byte[] retainedSnapshot;
		try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0)) {
			CanonicalStagedInput.ValueChunk first = cursor.nextChunk(Long.MAX_VALUE, 2);
			assertThat(first.records()).hasSize(2);
			retainedKey = first.records().getFirst().canonicalKey();
			retainedSnapshot = retainedKey.clone();
			append(cursorRecords, 0, first.records());
			CanonicalStagedInput.ValueChunk second = cursor.nextChunk(Long.MAX_VALUE, 2);
			assertThat(second.records()).hasSize(2);
			append(cursorRecords, 0, second.records());
			CanonicalStagedInput.ValueChunk last = cursor.nextChunk(Long.MAX_VALUE, 2);
			assertThat(last.records()).hasSize(1);
			append(cursorRecords, 0, last.records());
			assertThat(cursor.nextChunk(Long.MAX_VALUE, 2)).isNull();
		}

		assertThat(retainedKey).containsExactly(retainedSnapshot);
		assertThat(cursorRecords).containsExactlyElementsOf(visitorRecords);
		assertThat(cursorRecords).containsExactlyElementsOf(expected.stream()
				.map(record -> view(0, record.routeHash(), record.roles(), record.key()))
				.toList());
	}

	@ParameterizedTest
	@MethodSource("codecs")
	void peeksExactRetainedBytesWithoutConsumingTheNextKey(BulkCodec codec) throws Exception {
		List<ExpectedRecord> expected = recordsForPartition(0, 2);
		writeFrames(bucketPath(temporaryDirectory, 0), codec, expected);
		CanonicalStagedInput input = stagedInput(codec);

		try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0)) {
			assertThat(cursor.peekNextRecordRetainedBytes()).isEqualTo(64L + expected.getFirst().key().length);
			CanonicalStagedInput.ValueRecord first = cursor.next();
			assertThat(first.canonicalKey()).containsExactly(expected.getFirst().key());
			assertThat(cursor.peekNextRecordRetainedBytes()).isEqualTo(64L + expected.get(1).key().length);
			CanonicalStagedInput.ValueRecord second = cursor.next();
			assertThat(second.canonicalKey()).containsExactly(expected.get(1).key());
			assertThat(cursor.peekNextRecordRetainedBytes()).isEqualTo(-1L);
		}
	}

	@ParameterizedTest
	@MethodSource("codecs")
	void emptyOrMissingPartitionIsImmediatelyExhausted(BulkCodec codec) throws Exception {
		CanonicalStagedInput input = stagedInput(codec);
		Files.createDirectories(temporaryDirectory.resolve("value-buckets"));

		try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(1)) {
			assertThat(cursor.nextChunk(1024, 8)).isNull();
		}
	}

	@Test
	void rejectsCrossPartitionAndTruncatedValueRecords() throws Exception {
		BulkCodec codec = BulkCodec.level(9);
		List<ExpectedRecord> records = recordsForPartition(1, 1);
		Path bucket = bucketPath(temporaryDirectory, 0);
		Files.createDirectories(bucket.getParent());
		try (DataOutputStream output = BulkLz4.output(bucket, codec)) {
			ExpectedRecord record = records.getFirst();
			writeRecord(output, record);
		}
		CanonicalStagedInput input = stagedInput(codec);
		try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0)) {
			assertThatThrownBy(() -> cursor.nextChunk(1024, 8))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("different partition");
		}

		Files.delete(bucket);
		ExpectedRecord truncated = recordsForPartition(0, 1).getFirst();
		try (DataOutputStream output = BulkLz4.output(bucket, codec)) {
			output.writeLong(truncated.routeHash());
			output.writeByte(CanonicalStatementStager.ROLE_SUBJECT);
			output.writeInt(16);
			output.write(new byte[] { 1, 2, 3 });
		}
		try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0)) {
			assertThatThrownBy(() -> cursor.nextChunk(1024, 8))
					.isInstanceOf(IOException.class)
					.hasMessageContaining("Truncated");
		}
	}

	@Test
	void rejectsOversizedDeclaredKeyLengthWhilePeekingBeforeAllocatingIt() throws Exception {
		Path bucket = bucketPath(temporaryDirectory, 0);
		Files.createDirectories(bucket.getParent());
		try (DataOutputStream output = BulkLz4.output(bucket, BulkCodec.NONE)) {
			output.writeLong(0L);
			output.writeByte(CanonicalStatementStager.ROLE_SUBJECT);
			output.writeInt(1024 * 1024 * 1024 + 1);
		}

		try (CanonicalStagedInput.ValueCursor cursor = stagedInput(BulkCodec.NONE).openPartitionValueCursor(0)) {
			assertThatThrownBy(cursor::peekNextRecordRetainedBytes)
					.isInstanceOf(IOException.class)
					.hasMessageContaining("Invalid")
					.hasMessageContaining("length");
		}
	}

	@Test
	void schedulerLeaseCoversValueCursorLifetime() throws Exception {
		List<ExpectedRecord> expected = recordsForPartition(0, 1);
		writeFrames(bucketPath(temporaryDirectory, 0), BulkCodec.level(9), expected);
		CanonicalStagedInput input = stagedInput(BulkCodec.level(9));

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 1024 * 1024L, 2)) {
			try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0, scheduler)) {
				assertThat(scheduler.reservedMemoryBytes()).isPositive();
				assertThat(scheduler.reservedFileDescriptors()).isEqualTo(1);
				assertThat(scheduler.openFileHandles()).isEqualTo(1);
				assertThat(cursor.next()).isNotNull();
			}
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.reservedFileDescriptors()).isZero();
			assertThat(scheduler.openFileHandles()).isZero();
		}
	}

	@Test
	void admitsFixedValueCursorFloorWithoutBlockingAdaptiveAdmission() throws Exception {
		BulkCodec codec = BulkCodec.level(9);
		writeFrames(bucketPath(temporaryDirectory, 0), codec, recordsForPartition(0, 1));
		CanonicalStagedInput input = stagedInput(codec);
		long cursorMemoryBytes = BulkLz4.concatenatedInputMemoryBytes(codec);

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 1L, 1)) {
			try (CanonicalStagedInput.ValueCursor cursor = input.tryOpenPartitionValueCursor(0, scheduler)) {
				assertThat(cursor).isNotNull();
				assertThat(cursor.resourceLease()).isNotNull();
				assertThat(scheduler.reservedMemoryBytes()).isEqualTo(cursorMemoryBytes);
				assertThat(scheduler.effectiveMemoryMinimumBytes()).isEqualTo(cursorMemoryBytes);
				assertThat(scheduler.reservedFileDescriptors()).isEqualTo(1);
				assertThat(scheduler.openFileHandles()).isEqualTo(1);
				assertThat(input.tryOpenPartitionValueCursor(0, scheduler)).isNull();
				assertThat(cursor.next()).isNotNull();
			}
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.reservedFileDescriptors()).isZero();
			assertThat(scheduler.openFileHandles()).isZero();
		}
	}

	@Test
	void closesValueCursorInputBeforeReleasingItsBaseMemoryLease() throws Exception {
		BulkCodec codec = BulkCodec.level(9);
		writeFrames(bucketPath(temporaryDirectory, 0), codec, recordsForPartition(0, 1));
		CanonicalStagedInput input = stagedInput(codec);

		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, 1024 * 1024L, 1)) {
			try (CanonicalStagedInput.ValueCursor cursor = input.openPartitionValueCursor(0, scheduler)) {
				assertThat(cursor.next()).isNotNull();
				assertThat(cursor.next()).isNull();
				cursor.closeInput();
				assertThat(scheduler.reservedFileDescriptors()).isZero();
				assertThat(scheduler.openFileHandles()).isZero();
				assertThat(scheduler.reservedMemoryBytes()).isPositive();
			}
			assertThat(scheduler.reservedMemoryBytes()).isZero();
		}
	}

	@Test
	void rejectsPartitionsOutsideTheStagedInput() {
		CanonicalStagedInput input = stagedInput(BulkCodec.NONE);
		assertThatThrownBy(() -> input.openPartitionValueCursor(PARTITION_COUNT))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("out of range");
	}

	private CanonicalStagedInput stagedInput(BulkCodec codec) {
		BulkCompression compression = BulkCompression.parse("all=" + codec.token());
		return new CanonicalStagedInput(temporaryDirectory, PARTITION_COUNT, 0L, 0L, compression);
	}

	private static Path bucketPath(Path directory, int partition) {
		return CanonicalStatementStager.valueBucketPath(directory.resolve("value-buckets"), partition);
	}

	private static List<ExpectedRecord> recordsForPartition(int partition, int count) {
		List<ExpectedRecord> records = new ArrayList<>(count);
		for (int candidate = 0; records.size() < count; candidate++) {
			IRI value = SimpleValueFactory.getInstance().createIRI("urn:value:" + candidate);
			byte[] key = CanonicalTermCodec.encode(value);
			long hash = CanonicalTermCodec.routeHash64(key);
			if (((int) hash & (PARTITION_COUNT - 1)) == partition) {
				records.add(new ExpectedRecord(hash, CanonicalStatementStager.ROLE_SUBJECT, key));
			}
		}
		return records;
	}

	private static void writeFrames(Path path, BulkCodec codec, List<ExpectedRecord> records) throws IOException {
		for (int start = 0; start < records.size(); start += 2) {
			try (DataOutputStream output = BulkLz4.appendOutput(path, codec)) {
				for (int index = start; index < Math.min(records.size(), start + 2); index++) {
					writeRecord(output, records.get(index));
				}
			}
		}
	}

	private static void writeRecord(DataOutputStream output, ExpectedRecord record) throws IOException {
		output.writeLong(record.routeHash());
		output.writeByte(record.roles());
		output.writeInt(record.key().length);
		output.write(record.key());
	}

	private static void append(List<String> destination, int partition,
			List<CanonicalStagedInput.ValueRecord> records) {
		for (CanonicalStagedInput.ValueRecord record : records) {
			destination.add(view(partition, record.routeHash(), record.roles(), record.canonicalKey()));
		}
	}

	private static String view(int partition, long routeHash, int roles, byte[] key) {
		return partition + ":" + routeHash + ":" + roles + ":" + HexFormat.of().formatHex(key);
	}

	private record ExpectedRecord(long routeHash, int roles, byte[] key) {
	}
}
